@if (filled($links))
    <ul {{ $attributes->merge(['class' => 'flex flex-wrap items-center gap-2.5']) }}>
        @foreach ($links as $network => $url)
            @continue (! isset($icons[$network]))
            <li>
                {{-- noopener noreferrer: these point off-site, and the opener
                     handle is not something a third party needs. --}}
                <a href="{{ $url }}" target="_blank" rel="noopener noreferrer"
                   title="{{ $labels[$network] }}" aria-label="{{ $labels[$network] }}"
                   class="flex size-9 items-center justify-center rounded-full border border-stone-200 bg-white
                          text-stone-500 transition hover:border-brand-300 hover:bg-brand-50 hover:text-brand-700">
                    <svg class="size-4" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                        <path d="{{ $icons[$network] }}"/>
                    </svg>
                </a>
            </li>
        @endforeach
    </ul>
